    pos=g.node('GeometryNodeInputPosition','Metric height coordinates').outputs[0]
    index=g.node('GeometryNodeInputIndex','Actual quad corner').outputs[0]
    ids=[];points=[]
    for shift in (0,-1,1):
        corner=index
        if shift:
            at=g.node('GeometryNodeOffsetCornerInFace','Adjacent quad corner '+str(shift))
            g.set(index,at.inputs['Corner Index']);at.inputs['Offset'].default_value=shift
            corner=at.outputs['Corner Index']
        vertex=g.node('GeometryNodeVertexOfCorner','Quad corner vertex '+str(shift))
        g.set(corner,vertex.inputs['Corner Index']);ids.append(vertex.outputs['Vertex Index'])
        p=g.sample(geometry,pos,ids[-1],'FLOAT_VECTOR')
        points.append(g.xyz(g.component(p,'X'),g.component(p,'Y')))
    a=g.vector('SUBTRACT',points[1],points[0]);b=g.vector('SUBTRACT',points[2],points[0])
    la=g.vector('LENGTH',a);lb=g.vector('LENGTH',b)
